const safePath=(path:string)=>typeof path==='string'&&path.length>0&&path.split('.').every(segment=>segment.length>0&&!['__proto__','prototype','constructor'].includes(segment));
function valueAt(value:unknown,path:string):unknown {if(!safePath(path))fail('필드 경로가 잘못되었습니다.');let current=value;for(const segment of path.split('.')){if(!current||typeof current!=='object'||!Object.hasOwn(current,segment))return undefined;current=(current as Record<string,unknown>)[segment];}return current;}
