function outputSchema(node:Extract<WorkflowNode,{type:'ai'}>,unitIds:string[]){const properties:Record<string,unknown>={unitId:{type:'string',enum:unitIds},issues:{type:'array',items:{type:'string'}}};if(node.config.mode==='operations')properties.operations={type:'array',items:{type:'object'}};else properties.text={type:'string'};if(node.config.mode==='review')properties.passed={type:'boolean'};return {type:'object',properties:{items:{type:'array',minItems:unitIds.length,maxItems:unitIds.length,items:{type:'object',properties,required:Object.keys(properties),additionalProperties:false}}},required:['items'],additionalProperties:false};}
